func:
// Passo de idempotencia: prepara o filtro para apagar os documentos
// de ATL em weather_raw antes de recarregar. Assim cada execucao
// deixa exatamente 744 documentos, sem duplicados.
msg.payload = [{ airport_code: "ATL" }]; // filtro do deleteMany
return msg;

// Transforma a resposta da Open-Meteo (arrays paralelos) em 1 documento por hora.
// observed_at fica em hora LOCAL de Atlanta (America/New_York), sem conversao,
// para permitir join direto com os horarios locais do BTS.

const data = msg.payload;

if (!data || !data.hourly || !Array.isArray(data.hourly.time)) {
    node.error("Resposta inesperada da Open-Meteo", msg);
    return null;
}

function naiveIso(t) {
    if (t.length === 13) return t + ":00:00"; // ex.: 2025-01-01T00
    if (t.length === 16) return t + ":00";    // ex.: 2025-01-01T00:00
    return t;
}

const h = data.hourly;
const ingestedAt = new Date().toISOString();
const docs = h.time.map(function (t, i) {
    return {
        source: "open_meteo",
        airport_code: "ATL",
        observed_at: naiveIso(t),
        temperature_c: h.temperature_2m ? h.temperature_2m[i] : null,
        precipitation_mm: h.precipitation ? h.precipitation[i] : null,
        wind_speed_kmh: h.wind_speed_10m ? h.wind_speed_10m[i] : null,
        weather_code: h.weather_code ? h.weather_code[i] : null,
        latitude: data.latitude,
        longitude: data.longitude,
        timezone: data.timezone,
        utc_offset_seconds: data.utc_offset_seconds,
        ingested_at: ingestedAt
    };
});

msg.count = docs.length;
msg.payload = [ docs ]; // array passado como argumento do insertMany
return msg;
